 $$('.more').forEach(function(b){b.addEventListener('click',function(){var id=b.getAttribute('aria-controls'),el=R.getElementById(id),was=el.classList.contains('open');show(was?null:id);
   if(!was&&!RM)setTimeout(function(){el.scrollIntoView({behavior:'smooth',block:'nearest'})},260)})});
 
 
 /* menu */
 var hdr=$('#hdr'),nav=$('#nav'),drops=$$('.has-drop'),openEl=null,ot,ct,bg=$('#burger');
